{
  "summary": "To apply custom animations in LibreOffice Impress, open the presentation and select a slide from the slides pane. Select a text box by clicking on its text and border, then navigate to the tasks pane and open the Custom Animation panel. Clicking Add opens the Custom Animation dialog box on the Entrance tab, which governs how objects appear on the slide. Various animation effects, such as Diagonal Squares, Wedge, and Diamond under the Basic category, can be assigned to different text boxes, and their display speeds can be adjusted to Slow or Medium. Added animations are listed chronologically in the animations box and can be previewed using the Play button, either individually or simultaneously by holding the Shift key. Furthermore, double-clicking any listed animation opens the Effect Options dialog box. Users can modify custom properties such as motion direction under the Effects tab or introduce start delays under the Timing tab to refine presentation effects.",
  "facts": [
    {
      "fact": "The sampleimpress.odp presentation is opened to begin the tutorial.",
      "evidence": "पहले प्रस्तुति sampleimpress odp खोलें"
    },
    {
      "fact": "A text box is selected by clicking on its text and then clicking on the visible border.",
      "evidence": "text पर click करें और फिर दिखाई दे रहे border पर click करें"
    },
    {
      "fact": "The entrance tab controls the way an object appears on the screen.",
      "evidence": "entrance टैब screen पर वस्तु के प्रदर्शन के तरीके को नियंत्रित करता है"
    },
    {
      "fact": "The diagonal squares animation is selected under the basic category.",
      "evidence": "basic के नीचे diagonal squares चुनें"
    },
    {
      "fact": "The wedge animation under basic animation is chosen with the speed set to medium.",
      "evidence": "basic animation के नीचे wedge चुनें गति को medium set करें"
    },
    {
      "fact": "Multiple animations can be selected for preview by holding down the Shift key.",
      "evidence": "आप प्रिव्यू के लिए एक से भी अधिक animation चुन सकते हैं यह करने के लिए shift की पकड़कर रखें"
    },
    {
      "fact": "The order of animations can be modified using the change order buttons.",
      "evidence": "आप change order buttons का उपयोग करके animation के क्रम को भी बदल सकते हैं"
    },
    {
      "fact": "Double-clicking the first animation in the list opens the effects options dialog box.",
      "evidence": "सूची में पहले animation पर doubleclick करें यह diagonal squares option है effects options dialog box प्रदर्शित होता है"
    },
    {
      "fact": "The animation direction can be adjusted to from right to top under settings.",
      "evidence": "settings में direction dropdown पर click करें और from right to top चुनें"
    },
    {
      "fact": "An animation delay can be increased in the delay field under the timing tab.",
      "evidence": "timing टैब पर click करें delay field में delay को 10 sec तक बढाएँ"
    }
  ]
}
